import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { mkdir, unlink, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { EnvironmentVariables } from '../../config/env.validation.js';
import { StorageService } from './storage.service.js';

/** Public URL path of the product images, outside the API prefix (spec 03 §7.4). */
export const UPLOADS_URL_PATH = '/uploads';
export const PRODUCTS_FOLDER = 'products';

// Keys are generated by the server (<uuid>.webp, <uuid>_thumb.webp). Anything
// else is rejected so a key can never escape the folder ("../", "/", "\").
const SAFE_KEY = /^[A-Za-z0-9_-]+\.[a-z0-9]+$/;

/** Stores product images in <UPLOADS_DIR>/products, served at /uploads/products. */
@Injectable()
export class LocalDiskStorage extends StorageService {
  private readonly folder: string;
  private readonly publicBaseUrl: string;

  constructor(config: ConfigService<EnvironmentVariables, true>) {
    super();
    this.folder = join(resolve(config.get('UPLOADS_DIR', { infer: true })), PRODUCTS_FOLDER);
    this.publicBaseUrl = config.get('PUBLIC_BASE_URL', { infer: true }).replace(/\/+$/, '');
  }

  async save(key: string, buffer: Buffer): Promise<void> {
    await mkdir(this.folder, { recursive: true });
    await writeFile(this.pathOf(key), buffer);
  }

  async delete(key: string): Promise<void> {
    try {
      await unlink(this.pathOf(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
        throw error;
      }
    }
  }

  getPublicUrl(key: string): string {
    this.assertSafeKey(key);
    return `${this.publicBaseUrl}${UPLOADS_URL_PATH}/${PRODUCTS_FOLDER}/${key}`;
  }

  private pathOf(key: string): string {
    this.assertSafeKey(key);
    return join(this.folder, key);
  }

  private assertSafeKey(key: string): void {
    if (!SAFE_KEY.test(key)) {
      throw new Error(`Invalid storage key: ${key}`);
    }
  }
}
